using Npgsql;
using LoyaltyService.Application;
using LoyaltyService.Domain;
namespace LoyaltyService.Infrastructure; public sealed class PostgresLoyaltyRepository(string cs) : ILoyaltyRepository { private NpgsqlConnection Db() => new(cs); private static LoyaltyStatus Status(int n) => n >= 20 ? LoyaltyStatus.GOLD : n >= 10 ? LoyaltyStatus.SILVER : LoyaltyStatus.BRONZE; private static int Discount(LoyaltyStatus s) => s switch { LoyaltyStatus.GOLD => 10, LoyaltyStatus.SILVER => 7, _ => 5 }; public async Task<Loyalty> GetOrCreateAsync(string u, CancellationToken ct) { await using var db = Db(); await db.OpenAsync(ct); await using (var c = new NpgsqlCommand("INSERT INTO loyalty(username,reservation_count,status,discount) VALUES(@u,0,'BRONZE',5) ON CONFLICT(username) DO NOTHING", db)) { c.Parameters.AddWithValue("u", u); await c.ExecuteNonQueryAsync(ct); } return await Read(db, u, ct); } public async Task<Loyalty> ChangeCountAsync(string u, int d, CancellationToken ct) { var x = await GetOrCreateAsync(u, ct); var n = Math.Max(0, x.ReservationCount + d); var s = Status(n); await using var db = Db(); await db.OpenAsync(ct); await using var c = new NpgsqlCommand("UPDATE loyalty SET reservation_count=@c,status=@s,discount=@d WHERE username=@u", db); c.Parameters.AddWithValue("c", n); c.Parameters.AddWithValue("s", s.ToString()); c.Parameters.AddWithValue("d", Discount(s)); c.Parameters.AddWithValue("u", u); await c.ExecuteNonQueryAsync(ct); return new(u, n, s, Discount(s)); } private static async Task<Loyalty> Read(NpgsqlConnection db, string u, CancellationToken ct) { await using var c = new NpgsqlCommand("SELECT username,reservation_count,status,discount FROM loyalty WHERE username=@u", db); c.Parameters.AddWithValue("u", u); await using var r = await c.ExecuteReaderAsync(ct); await r.ReadAsync(ct); return new(r.GetString(0), r.GetInt32(1), Enum.Parse<LoyaltyStatus>(r.GetString(2)), r.GetInt32(3)); } }
